@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root{color-scheme:dark;--paper:#e9dfc6;--muted:#87928a;--orange:#f06b3d;--lime:#d8e56a;--ink:#111a1b;--panel:#172223;--line:rgba(232,222,193,.15)}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#0d1516;color:var(--paper);font-family:'DM Mono',monospace;touch-action:none}body{display:grid;place-items:center}button{font:inherit;color:inherit;cursor:pointer;border:0}#game-shell{position:relative;width:min(100vw,177.7778vh);height:min(100vh,56.25vw);aspect-ratio:16/9;overflow:hidden;background:#1a2a2a;box-shadow:0 12px 70px #0009;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated;image-rendering:crisp-edges}.scanlines{position:absolute;inset:0;pointer-events:none;z-index:2;opacity:.13;background:repeating-linear-gradient(0deg,transparent 0 3px,#0b1111 4px);mix-blend-mode:multiply}.screen{position:absolute;inset:0;z-index:3}.title-screen{background:linear-gradient(90deg,rgba(13,22,22,.95) 0%,rgba(13,22,22,.8) 44%,rgba(13,22,22,.05) 100%);display:flex;align-items:center;padding:0 10.5%}.title-copy{margin-top:-1%}.eyebrow{font-size:clamp(7px,.86vw,11px);letter-spacing:.18em;color:#adb6a1;margin:0 0 10px}.live-dot{display:inline-block;width:7px;height:7px;background:var(--orange);border-radius:50%;margin-right:7px;box-shadow:0 0 10px #f06b3d99}.title-copy h1{font:900 clamp(54px,9vw,116px)/.8 'Barlow Condensed',sans-serif;letter-spacing:-.04em;margin:0;color:var(--paper);text-shadow:5px 5px 0 #111a1b}.title-copy h1 span{display:block;color:var(--orange)}.tagline{font:500 clamp(11px,1.35vw,17px) 'Barlow Condensed',sans-serif;letter-spacing:.16em;text-transform:uppercase;margin:20px 0 26px;color:#c7c6ae}.primary-btn,.secondary-btn{padding:13px 22px;background:var(--orange);color:#171a18;font:800 13px 'Barlow Condensed',sans-serif;letter-spacing:.16em;min-width:170px;text-align:left;box-shadow:4px 4px 0 #7f3a28;transition:transform .15s,filter .15s}.primary-btn span{float:right;font-size:18px;line-height:12px}.primary-btn:hover,.secondary-btn:hover{transform:translate(-2px,-2px);filter:brightness(1.12)}.microcopy{font-size:8px;color:#85918a;letter-spacing:.08em;margin-top:17px}.title-stamp{position:absolute;right:11%;top:24%;width:100px;height:100px;border:1px solid #d5daac66;border-radius:50%;display:grid;place-items:center;transform:rotate(12deg);color:#d5daac99;text-align:center;font:700 13px/.9 'Barlow Condensed',sans-serif;letter-spacing:.12em}.title-stamp b{position:absolute;bottom:15px;font:8px 'DM Mono',monospace}.title-bottom{position:absolute;left:4%;right:4%;bottom:4%;display:flex;justify-content:space-between;font-size:8px;letter-spacing:.12em;color:#a6afa2}.topbar{position:absolute;z-index:5;top:0;left:0;right:0;height:68px;padding:10px 24px;display:flex;align-items:center;gap:14px;background:linear-gradient(#111a1be8,#111a1b00)}.topbar[hidden],.screen[hidden],.control-hint[hidden],.aim-pad[hidden],.fire-btn[hidden]{display:none}.icon-btn{width:34px;height:34px;border:1px solid var(--line);background:#142020a8;color:var(--paper);font-size:20px}.mission-label{display:grid;gap:2px;min-width:145px}.mission-label .eyebrow{font-size:7px;margin:0;color:#a6afa2}.mission-label strong{font:700 18px 'Barlow Condensed',sans-serif;letter-spacing:.1em}.wind-pill,.ammo-pill{height:30px;display:flex;align-items:center;gap:8px;padding:0 11px;background:#111b1dbd;border:1px solid var(--line);font-size:9px;letter-spacing:.08em}.wind-icon{color:var(--lime);font-size:17px}.ammo-pill{margin-left:auto}.ammo-pill i{width:7px;height:7px;background:var(--orange);display:block;border-radius:50%;box-shadow:0 0 8px #f06b3d}.ammo-pill small{color:#8e9a92;font-size:7px}.sound-btn{font-size:15px}.map-screen{background:linear-gradient(120deg,#101a1beF,#101a1bbb),radial-gradient(ellipse at 75% 55%,#415347,#182627 55%);padding:7% 9% 5%;display:flex;flex-direction:column}.screen-heading .eyebrow{color:var(--orange);margin-bottom:5px}.screen-heading h2{font:800 clamp(30px,5vw,56px)/.9 'Barlow Condensed',sans-serif;margin:0;letter-spacing:.03em}.screen-heading h2 span{color:var(--lime)}.subhead{font-size:9px;color:#a4ada1;margin:8px 0 22px}.level-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;max-width:870px}.level-card{position:relative;text-align:left;padding:0;background:#192627;border:1px solid #c8d2ba26;min-height:145px;transition:transform .15s,border .15s;overflow:hidden}.level-card:hover{transform:translateY(-4px);border-color:#d8e56a99}.level-card.locked{opacity:.42;cursor:not-allowed}.card-art{height:79px;position:relative;overflow:hidden;background:#576d63}.card-art:before,.card-art:after{content:'';position:absolute;bottom:0;background:#1c302c}.card-art:before{left:0;width:100%;height:25%;clip-path:polygon(0 60%,16% 10%,34% 55%,54% 0,74% 58%,100% 20%,100% 100%,0 100%)}.card-art:after{width:11px;height:30px;background:#e8dfc6;left:50%;bottom:12px;box-shadow:15px 3px 0 -3px #f06b3d,-22px 4px 0 -4px #d8e56a}.level-card:nth-child(2) .card-art{background:#a27e56}.level-card:nth-child(3) .card-art{background:#547781}.level-card:nth-child(4) .card-art{background:#766c69}.level-card:nth-child(5) .card-art{background:#354a62}.level-card:nth-child(2) .card-art:after{height:40px;width:3px;background:#e9dfc6;box-shadow:0 0 0 6px #263534}.level-card:nth-child(3) .card-art:after{width:15px;height:15px;border-radius:50%;background:#f06b3d;bottom:24px}.level-card:nth-child(4) .card-art:after{height:12px;width:28px;background:#d8e56a;bottom:31px}.level-card:nth-child(5) .card-art:after{height:22px;width:22px;border-radius:50%;background:#f0e2a7;bottom:22px}.card-number{position:absolute;top:8px;left:8px;color:#f2ebd6;font-size:8px;text-shadow:0 1px 3px #000}.card-info{padding:8px 10px}.card-info b{display:block;font:700 14px 'Barlow Condensed',sans-serif;letter-spacing:.07em}.card-info small{font-size:7px;color:#9eaaa0;letter-spacing:.04em}.card-stars{position:absolute;right:8px;bottom:10px;color:var(--lime);font-size:8px}.map-footer{display:flex;justify-content:space-between;margin-top:auto;padding-top:14px;color:#88948c;font-size:7px;letter-spacing:.1em}.result-screen{display:grid;place-items:center;background:#101a1bc9}.result-card{width:min(440px,78%);padding:26px 30px;background:#172223f2;border:1px solid #d8e56a4c;box-shadow:8px 8px 0 #0b1111b8;text-align:center}.result-card .eyebrow{color:var(--lime);margin-bottom:6px}.result-card h2{font:900 clamp(35px,6vw,58px)/.9 'Barlow Condensed',sans-serif;margin:0}.stars{color:var(--lime);letter-spacing:8px;font-size:25px;margin:12px 0 4px}.result-card>p:not(.eyebrow){font-size:9px;color:#aab3a4}.result-stats{display:flex;justify-content:center;gap:28px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:12px 0;margin:18px 0;color:#87928a;font-size:7px;letter-spacing:.08em}.result-stats b{display:block;color:var(--paper);font-size:13px;margin-top:5px}.result-actions{display:flex;justify-content:center;gap:12px}.result-actions .primary-btn,.result-actions .secondary-btn{min-width:130px;text-align:center;padding:11px 12px}.result-actions .primary-btn span{float:none;margin-left:10px}.secondary-btn{background:transparent;color:var(--paper);border:1px solid #ddd6bf55;box-shadow:none}.control-hint{position:absolute;z-index:4;bottom:5%;left:5%;right:5%;display:flex;justify-content:space-between;pointer-events:none;color:#f0e8d0a6;font-size:8px;letter-spacing:.14em}.aim-pad{position:absolute;z-index:4;left:4%;bottom:10%;width:30%;height:28%;border:1px dashed #e6e1bf37;border-radius:4px;background:linear-gradient(135deg,#dce2c708,#dce2c700);display:grid;place-items:center;color:#e5e2c34c;pointer-events:none}.pad-cross{font-size:28px}.pad-label{position:absolute;bottom:8px;font-size:7px;letter-spacing:.12em}.fire-btn{position:absolute;z-index:6;right:4%;bottom:8%;width:112px;height:90px;background:var(--orange);color:#1a201d;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px;box-shadow:4px 5px 0 #713923;touch-action:none}.fire-btn:active,.fire-btn.pressed{transform:translate(2px,3px);box-shadow:1px 2px 0 #713923;filter:brightness(1.15)}.fire-glyph{font-size:21px;line-height:20px}.fire-btn b{font:900 19px 'Barlow Condensed',sans-serif;letter-spacing:.16em}.fire-btn small{font-size:6px;letter-spacing:.1em;opacity:.7}.orientation{display:none;position:fixed;inset:0;z-index:20;background:#101a1b;place-items:center;align-content:center;gap:12px;text-align:center}.orientation b{font:700 21px 'Barlow Condensed',sans-serif;letter-spacing:.12em}.orientation small{font-size:8px;color:#89968d;letter-spacing:.1em}.rotate-icon{font-size:40px;color:var(--lime);position:relative}.rotate-icon span{position:absolute;font-size:22px;right:-18px;top:-8px}@media (orientation:portrait) and (max-width:700px){.orientation{display:grid}#game-shell{width:100vw;height:100vh;aspect-ratio:auto}}@media(max-height:500px){.topbar{height:54px;padding:6px 16px}.map-screen{padding:5% 8% 3%}.subhead{margin:5px 0 12px}.card-art{height:64px}.level-card{min-height:125px}.fire-btn{width:92px;height:72px;bottom:5%}.aim-pad{bottom:7%}.result-card{padding:17px 24px}.stars{margin:6px 0}.result-stats{margin:10px 0;padding:8px 0}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 960, H = 540, groundY = 454;
  const $ = (id) => document.getElementById(id);
  const screens = ['title-screen', 'map-screen', 'result-screen'];
  const levels = [
    { name:'TIN TOWN', place:'DUSTY MAIN STREET', sky:'#e6a56c', far:'#bd805b', near:'#745647', wind:0, goal:3, shots:5, targets:[['bottle',490,397],['bottle',635,397],['plate',790,364]], obstacles:[[365,386,48,68]] },
    { name:'WINDMILL PASS', place:'THE OLD WIND FARM', sky:'#d4b77a', far:'#aa9169', near:'#57644c', wind:18, goal:3, shots:5, targets:[['plate',465,360],['bottle',637,397],['bell',785,300]], obstacles:[[365,354,39,100],[708,389,45,65]] },
    { name:'BLUE CANYON', place:'ECHOES IN THE GORGE', sky:'#83b5b1', far:'#638e88', near:'#3b5f59', wind:-20, goal:3, shots:5, targets:[['lamp',465,327],['bottle',642,396],['lamp',795,277]], obstacles:[[340,362,62,92],[540,415,80,39]] },
    { name:'NIGHT SHIFT', place:'ROOFTOPS AFTER DARK', sky:'#586c85', far:'#455568', near:'#293a47', wind:12, goal:3, shots:5, targets:[['drone',470,294],['drone',645,350],['drone',790,260]], obstacles:[[376,345,82,109],[570,390,64,64]] },
    { name:'LAST LIGHT', place:'THE LONELY LIGHTHOUSE', sky:'#dc946d', far:'#987168', near:'#3c5151', wind:-12, goal:4, shots:6, targets:[['bell',445,300],['bottle',570,400],['lamp',710,323],['plate',825,375]], obstacles:[[340,388,42,66],[625,391,47,63]] }
  ];
  const targetNames = ['clay bottles','tin plates','signal bells','harbor lamps','scout drones'];
  const titles = ['Tin Town','Windmill Pass','Blue Canyon','Night Shift','Last Light'];
  let state='title', levelIndex=0, targets=[], shots=0, gunOffset=0, aim=24, bullets=[], particles=[], sparks=[], elapsed=0, recoil=0, dragging=null, audioOn=true, unlocked=1, bestScores=Array(5).fill(0), lastShotHit=false;
  let audioCtx=null;
  try { const save=JSON.parse(localStorage.getItem('longshot-progress')||'{}'); unlocked=Math.max(1,Math.min(5,save.unlocked||1)); bestScores=save.bestScores||bestScores; } catch (_) {}
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function resize(){
    const ratio=window.devicePixelRatio||1;
    const rect=canvas.getBoundingClientRect();
    canvas.width=Math.max(1,Math.round(rect.width*ratio)); canvas.height=Math.max(1,Math.round(rect.height*ratio));
    ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0); ctx.imageSmoothingEnabled=false;
  }
  window.addEventListener('resize',resize); resize();
  function persist(){try{localStorage.setItem('longshot-progress',JSON.stringify({unlocked,bestScores}));}catch(_){}}
  function showScreen(name){screens.forEach(id=>$(id).hidden=id!==name);}
  function startLevel(index){
    levelIndex=index; const def=levels[index];
    targets=def.targets.map(([type,x,y],i)=>({type,x,y,alive:true,phase:i*2.1,baseY:y,hit:0}));
    bullets=[]; particles=[]; sparks=[]; shots=0; gunOffset=0; aim=24; elapsed=0; recoil=0; state='playing';
    showScreen(''); $('topbar').hidden=false; $('aim-pad').hidden=false; $('fire-btn').hidden=false; $('control-hint').hidden=false;
    $('mission-name').textContent=def.name; $('wind-label').textContent=`WIND ${def.wind>0?'+':''}${def.wind}`; $('shot-count').textContent='00';
    updateMap();
  }
  function toMap(){state='map';showScreen('map-screen');$('topbar').hidden=true;$('aim-pad').hidden=true;$('fire-btn').hidden=true;$('control-hint').hidden=true;updateMap();}
  function updateMap(){
    const grid=$('level-grid'); grid.innerHTML='';
    levels.forEach((level,i)=>{
      const available=i<unlocked; const card=document.createElement('button');card.className=`level-card${available?'':' locked'}`;card.disabled=!available;
      card.innerHTML=`<div class="card-art"><span class="card-number">OP. 0${i+1}</span></div><div class="card-info"><b>${titles[i]}</b><small>${level.place}</small></div><span class="card-stars">${'★'.repeat(Math.min(3,bestScores[i]||0))}${'☆'.repeat(3-Math.min(3,bestScores[i]||0))}</span>`;
      card.addEventListener('click',()=>startLevel(i));grid.appendChild(card);
    });
  }
  function finishLevel(){
    if(state!=='playing')return; state='result'; const score=Math.max(120,1000-shots*145); const stars=shots<=levels[levelIndex].shots-2?3:shots<=levels[levelIndex].shots?2:1;
    bestScores[levelIndex]=Math.max(bestScores[levelIndex]||0,stars);unlocked=Math.max(unlocked,Math.min(levels.length,levelIndex+2));persist();
    $('topbar').hidden=true;$('aim-pad').hidden=true;$('fire-btn').hidden=true;$('control-hint').hidden=true;
    $('result-kicker').textContent='OPERATION COMPLETE';$('result-title').textContent=shots<=levels[levelIndex].shots-2?'CLEAN HIT.':'TARGETS DOWN.';
    $('result-stars').textContent='★'.repeat(stars)+'☆'.repeat(3-stars);$('result-copy').textContent=shots<=levels[levelIndex].shots-2?'A tidy little piece of work.':'Every target accounted for. On to the next range.';
    $('result-shots').textContent=String(shots).padStart(2,'0');$('result-score').textContent=String(score).padStart(4,'0');
    $('next-btn').innerHTML=levelIndex<levels.length-1?'NEXT RANGE <span>→</span>':'BACK TO MAP <span>→</span>';showScreen('result-screen');updateMap();
  }
  $('play-btn').addEventListener('click',toMap);$('menu-btn').addEventListener('click',toMap);
  $('retry-btn').addEventListener('click',()=>startLevel(levelIndex));
  $('next-btn').addEventListener('click',()=>levelIndex<levels.length-1?startLevel(levelIndex+1):toMap());
  $('sound-btn').addEventListener('click',()=>{audioOn=!audioOn;$('sound-btn').textContent=audioOn?'♫':'♪';});
  function tone(freq,duration,type='square',volume=.035){
    if(!audioOn)return;try{audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch(_){}
  }
  function muzzle(){return {x:76+gunOffset+24,y:380};}
  function trajectory(){
    const m=muzzle(), a=aim*Math.PI/180, speed=690, def=levels[levelIndex]||levels[0];
    let x=m.x,y=m.y,vx=Math.cos(a)*speed,vy=-Math.sin(a)*speed,prev={x,y};
    for(let i=0;i<100;i++){
      const dt=.025;vx+=(def.wind*1.6)*dt;vy+=535*dt;x+=vx*dt;y+=vy*dt;
      const collision=collideAt(x,y,true); if(collision||y>=groundY||x>W-8||x<0)return {points:[prev,{x,y}],end:{x,y},hit:collision?.target||null,obstacle:collision?.obstacle||false};
      if(i%2===0)prev={x,y};
    }
    return {points:[prev,{x,y}],end:{x,y},hit:null};
  }
  function collideAt(x,y,preview=false){
    for(const o of (levels[levelIndex]||levels[0]).obstacles){if(x>o[0]-3&&x<o[0]+o[2]+3&&y>o[1]-3&&y<o[1]+o[3]+3)return {obstacle:true};}
    for(const t of targets){if(!t.alive)continue;const p=targetPos(t);const r=targetRadius(t);if((x-p.x)**2+(y-p.y)**2<r*r)return {target:t};}
    return null;
  }
  function targetRadius(t){return t.type==='drone'?18:t.type==='plate'?15:t.type==='lamp'?14:13;}
  function targetPos(t){let y=t.y;if(t.type==='drone')y=t.baseY+Math.sin(elapsed*1.8+t.phase)*16;if(t.type==='lamp')y=t.baseY+Math.sin(elapsed*1.2+t.phase)*6;return{x:t.x,y};}
  function shoot(){
    if(state!=='playing')return;shots++;$('shot-count').textContent=String(shots).padStart(2,'0');recoil=1;const m=muzzle(),a=aim*Math.PI/180,speed=690,wind=levels[levelIndex].wind;
    bullets.push({x:m.x,y:m.y,vx:Math.cos(a)*speed,vy:-Math.sin(a)*speed,age:0,trail:[]});tone(95,.22,'sawtooth',.045);
  }
  $('fire-btn').addEventListener('pointerdown',e=>{e.preventDefault();$('fire-btn').classList.add('pressed');shoot();});
  $('fire-btn').addEventListener('pointerup',()=> $('fire-btn').classList.remove('pressed'));
  $('fire-btn').addEventListener('pointercancel',()=> $('fire-btn').classList.remove('pressed'));
  canvas.addEventListener('pointerdown',e=>{
    const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H;
    if(state!=='playing')return;
    if(x>W*.69){shoot();return;}
    if(y<68)return;
    e.preventDefault();canvas.setPointerCapture(e.pointerId);dragging={id:e.pointerId,x,y,aim,offset:gunOffset};
  });
  canvas.addEventListener('pointermove',e=>{
    if(!dragging||e.pointerId!==dragging.id)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*W,y=(e.clientY-r.top)/r.height*H;
    const dx=x-dragging.x,dy=y-dragging.y;aim=clamp(dragging.aim-dy*.13+dx*.025,3,72);gunOffset=clamp(dragging.offset+dx*.12,-22,58);
  });
  const clearDrag=()=>dragging=null;canvas.addEventListener('pointerup',clearDrag);canvas.addEventListener('pointercancel',clearDrag);
  window.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();shoot();}if(e.key==='Escape'&&state==='playing')toMap();if(state==='playing'&&e.key==='ArrowUp')aim=clamp(aim+2,3,72);if(state==='playing'&&e.key==='ArrowDown')aim=clamp(aim-2,3,72);});
  function addBurst(x,y,color,n=18){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=35+Math.random()*180;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-35,life:.45+Math.random()*.6,color,size:2+Math.random()*3});}}
  function update(dt){
    elapsed+=dt;recoil=Math.max(0,recoil-dt*4);
    if(state==='playing'){
      const wind=levels[levelIndex].wind;
      bullets.forEach(b=>{b.age+=dt;b.trail.push({x:b.x,y:b.y});if(b.trail.length>8)b.trail.shift();b.vx+=wind*1.6*dt;b.vy+=535*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;
        const c=collideAt(b.x,b.y);if(c){if(c.target){c.target.alive=false;const p=targetPos(c.target);addBurst(p.x,p.y,c.target.type==='lamp'?'#f7d775':'#f06b3d',24);tone(460,.12,'triangle',.04);tone(710,.16,'sine',.03);}else{addBurst(b.x,b.y,'#d3cba4',8);tone(150,.08,'square',.025);}b.dead=true;}
        if(b.y>=groundY||b.x>W||b.x<0||b.age>3)b.dead=true;
      });
      bullets=bullets.filter(b=>!b.dead);
      if(targets.every(t=>!t.alive)&&bullets.length===0)finishLevel();
    }
    particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=210*dt;p.vx*=.98;});particles=particles.filter(p=>p.life>0);
  }
  function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
  function line(x1,y1,x2,y2,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();}
  function drawBackground(){
    const def=levels[levelIndex]||levels[0];
    ctx.fillStyle=def.sky;ctx.fillRect(0,0,W,H);
    // chunky, layered pixel skies
    for(let i=0;i<6;i++)rect((i*177+32)%W,80+(i%3)*36,80+(i%2)*35,4,'#fff1c414');
    rect(0,280,W,95,def.far);
    if(levelIndex===0){
      // sunbaked buttes
